"""Shared opt-in half-profile surface branch; ordinary geometry is preserved."""
import bpy

from . import half_profile_relax_nodes,half_profile_spine_nodes

NAME='Street Blosm / Half-profile surface backend v2'


def build():
    existing=bpy.data.node_groups.get(NAME)
    if existing:return existing
    from ..kernel.backend_runtime import Graph, V, rm, named, choose, bounded
    from ..kernel import backend
    from ..kernel import prepare

    # The base kernel owns the unchanged direct-quad and height evaluators.
    # Reuse them; constructing this optional branch must not replace their
    # datablocks or disconnect other scene objects from their existing trees.
    base=bpy.data.node_groups[backend.NAME]
    component=lambda name:next(n.node_tree for n in base.nodes if n.type=='GROUP' and n.label==name)
    mesh=component('Direct quad construction')
    fraction=component('Analytic surface fraction')
    crown=component('Incoming crown reconciliation')
    g=Graph(NAME)
    g.socket('Geometry','NodeSocketGeometry');g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    for key,kind,default in (('Mesh Resolution','NodeSocketInt',1),('Height Exaggeration','NodeSocketFloat',10.),
        ('Grass','NodeSocketBool',False),('Material','NodeSocketMaterial',None),('Reference Elevation','NodeSocketFloat',0.)):
        g.socket(key,kind,default=default)
    inp=g.node('NodeGroupInput')
    shape=g.node('GeometryNodeGroup','Bound internal half-profile guides');shape.node_tree=half_profile_spine_nodes.build()
    g.bind(inp.outputs['Geometry'],shape.inputs['Geometry'])
    views={key:rm.split(g,shape.outputs['Geometry'],tag) for tag,key in enumerate(('Header','Arms','Patches','Pieces'))}
    factor=g.math('POWER',2.,bounded(g,V(g,inp.outputs['Mesh Resolution']),1.,4.)-1.)

    def call(tree,geometry=None,keys=()):
        n=g.node('GeometryNodeGroup',tree.name.removeprefix('Street Blosm / '));n.node_tree=tree
        if geometry is not None:g.bind(geometry,n.inputs['Geometry'])
        for key in keys:g.bind(views[key],n.inputs[key])
        return n

    node=call(mesh,keys=('Arms','Patches','Pieces','Header'))
    g.bind(factor,node.inputs['Factor']);g.bind(inp.outputs['Grass'],node.inputs['Grass'])
    raw=node.outputs['Geometry']
    node=call(half_profile_relax_nodes.build(),raw,('Arms',))
    intervals=prepare.stat(g,shape.outputs['Geometry'],named(g,'nu_base','INT'))*factor
    g.bind(intervals,node.inputs['Grid Intervals'])
    grass=g.store(raw,'initial_xy',g.position(),'POINT','FLOAT_VECTOR')
    grass=g.store(grass,'fixed_xy',True,'POINT','BOOLEAN')
    geo=choose(g,inp.outputs['Grass'],grass,node.outputs['Geometry'],'GEOMETRY')
    geo=call(fraction,geo,('Arms','Patches','Pieces')).outputs['Geometry']
    geo=call(crown,geo,('Arms','Header')).outputs['Geometry']
    x,y,_=g.separate(g.position())
    z=named(g,'profile_fraction')*named(g,'crown_amplitude')*V(g,inp.outputs['Height Exaggeration'])
    geo=g.setpos(geo,g.xyz(x,y,z+V(g,inp.outputs['Reference Elevation'])))
    material=g.node('GeometryNodeSetMaterial');g.bind(geo,material.inputs['Geometry']);g.bind(inp.outputs['Material'],material.inputs['Material'])
    legacy=g.node('GeometryNodeGroup','Unchanged ordinary junction surface');legacy.node_tree=base
    for key in ('Geometry','Mesh Resolution','Height Exaggeration','Grass','Material','Reference Elevation'):
        g.bind(inp.outputs[key],legacy.inputs[key])
    half=prepare.stat(g,views['Arms'],g.math('ABSOLUTE',named(g,'half_profile','INT')))
    result=choose(g,half,material.outputs['Geometry'],legacy.outputs['Geometry'],'GEOMETRY')
    out=g.node('NodeGroupOutput');g.bind(result,out.inputs['Geometry'])
    g.g['scope']='Opt-in half-profile construction; ordinary junctions use the unchanged base backend'
    return g.g
